function repeat(text, n, sep){ n=Math.floor(+n); if(isNaN(n)||n<0) return {error:'次数须为非负整数'};
  sep=(sep==null)?'':String(sep); var out=[]; for(var i=0;i<n;i++) out.push(text); return out.join(sep); }
var EXPORTS={repeat:repeat};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.TextRepeatForgePure = EXPORTS; }
